namespace SE.Roleplay.Launcher.Models;
public sealed class ServerEntry { public string Id { get; set; } = ""; public string Name { get; set; } = "Unnamed server"; public string Description { get; set; } = ""; public string Address { get; set; } = ""; public int Port { get; set; } = 27016; public string Region { get; set; } = "Unknown"; public string GameMode { get; set; } = "Roleplay"; public int Players { get; set; } public int MaxPlayers { get; set; } public bool IsOnline { get; set; } public string Version { get; set; } = ""; public string Endpoint => $"{Address}:{Port}"; public string Population => MaxPlayers > 0 ? $"{Players}/{MaxPlayers}" : $"{Players} players"; public string Status => IsOnline ? "ONLINE" : "OFFLINE"; }